139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
142	        HttpHeaders headers = new HttpHeaders();
143	        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
144	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
145	        if (existingId != null) {
146	            Owner existing = this.clinicService.findOwnerById(existingId);
147	            if (existing != null) {
148	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
149	            }
150	        }
151	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
152	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
153	        owner.setTelephone(normalizedTelephone);
154	        owner.setEmail(normalizeEmail(owner.getEmail()));
155	        applyAddress(owner);
156	        validatePostcode(owner.getCity(), owner.getPostcode());
157	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
158	        if (effectiveRegistrationDate == null) {
159	            effectiveRegistrationDate = LocalDate.now();
160	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
161	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
162	                "registrationDate must not be later than the current server date");
163	        }
164	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
165	        owner.setRegistrationDate(effectiveRegistrationDate);
166	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
167	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
168	                "the maximum number of owners that may be created today has been reached");
169	        }
170	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
171	        // The household id is deterministic (derived from the last name and postcode), so every
172	        // owner is keyed to its household automatically, regardless of creation order.
173	        this.clinicService.assignHousehold(owner);
174	        // An owner joining an existing household is now admitted rather than rejected; their
175	        // membership level is instead capped relative to the household (see the level-ceiling rule
176	        // applied via the membershipLevelCap below).
177	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
178	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
179	            throw new ResponseStatusException(HttpStatus.CONFLICT,
180	                "an owner with the same identity already exists");
181	        }
182	        int ownersInCity = countOwnersInCity(owner.getCity());
183	        if (ownersInCity >= CITY_CAPACITY) {
184	            throw new ResponseStatusException(HttpStatus.CONFLICT,
185	                "city has reached its maximum number of owners");
186	        }
187	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
188	        owner.setMemberId(memberIdFor(owner));
189	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
190	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
191	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
192	        owner.setBulkSignupWarning(
193	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
194	        // A declared household member (one created with 'sharesHousehold' that joins an existing
195	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
196	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
197	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
198	        owner.setPossibleDuplicate(softDuplicate != null);
199	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
200	        this.clinicService.saveOwner(owner);
201	        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
204	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
205	            ownerDto.getMembershipLevel());
206	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
207	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
208	        AUDIT.info(event.toJson());
209	        NOTIFY.info("welcome queued: ownerId={} memberId={}", owner.getId(), owner.getMemberId());
210	        headers.setLocation(UriComponentsBuilder.newInstance()
211	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
212	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
213	    }
