312	    /**
313	     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
314	     * An owner's primary identifier is its {@code memberId}; this single accessor is the one place that
315	     * decides which field is primary, so the audit event always carries the member id.
316	     *
317	     * @param owner the created owner
318	     * @return the owner's current primary identifier
319	     */
320	    private String primaryIdentifier(Owner owner) {
321	        return owner.getMemberId();
322	    }
323	
324	    /**
325	     * Builds the member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'} where REGION is
326	     * the region derived from the owner's postcode (preferring the postcode, falling back to the city
327	     * table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}), FY is the two-digit fiscal
328	     * year (starting 1 July; see {@link OwnerMapper#fiscalYear(LocalDate)}) of the business-day-adjusted
329	     * registration date, HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of the
330	     * owner's normalized E.164 telephone concatenated with the last name, and CHK is a single Luhn check
331	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'} (see
332	     * {@link IdentityKeyUtils#luhnCheckDigit(String)}), e.g. {@code 'NSW271A2B3C4D5'}. The id carries no
333	     * sequence number, so its base form is a stable function of the owner's region, fiscal year and
334	     * telephone/last-name identity rather than of creation order.
335	     *
336	     * <p>When that computed id already belongs to an existing owner it is de-duplicated by appending
337	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields an id no existing owner
338	     * already has; the de-duplicated id is returned.
339	     *
340	     * @param owner the owner being created, with its telephone already normalized to E.164 form and its
341	     *              registration date already business-day-adjusted
342	     * @return the assigned, collision-free member id
343	     */
344	    private String memberIdFor(Owner owner) {
345	        String region = ownerMapper.regionOf(owner);
346	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
347	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
348	            .substring(0, 8);
349	        String base = region + fy + hash8;
350	        String memberId = base + IdentityKeyUtils.luhnCheckDigit(base);
351	        if (!isMemberIdInUse(memberId)) {
352	            return memberId;
353	        }
354	        int n = 2;
355	        String candidate = memberId + "-" + n;
356	        while (isMemberIdInUse(candidate)) {
357	            n++;
358	            candidate = memberId + "-" + n;
359	        }
360	        return candidate;
361	    }
362	
363	    /**
364	     * Determines whether any existing owner already carries the given {@code memberId}, compared
365	     * exactly. Called while assigning a new owner's member id so collisions can be de-duplicated.
366	     *
367	     * @param memberId the candidate member id to look for
368	     * @return {@code true} if an existing owner already has that member id
369	     */
370	    private boolean isMemberIdInUse(String memberId) {
371	        for (Owner existing : this.clinicService.findAllOwners()) {
372	            if (memberId.equals(existing.getMemberId())) {
373	                return true;
374	            }
375	        }
376	        return false;
377	    }
