379	    /**
380	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
381	     * owner's city already contains this many owners.
382	     */
383	    private static final int CITY_CAPACITY = 50;
384	
385	    /**
386	     * The number of owners a city must already contain before a new owner in it is flagged with
387	     * {@code capacityWarning}. Once the city holds this many owners (but fewer than
388	     * {@link #CITY_CAPACITY}), the create still succeeds but is flagged as approaching the capacity
389	     * limit.
390	     */
391	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
392	
393	    /**
394	     * The maximum number of owners that may be created on a single day. A create is rejected with
395	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
396	     * {@code registrationDate}.
397	     */
398	    private static final int DAILY_CREATE_LIMIT = 100;
399	
400	    /**
401	     * The number of owners that must already have been created for the current day before a new
402	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
403	     * owners already carry today's {@code registrationDate}.
404	     */
405	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
406	
407	    /**
408	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
409	     * of these dates is rolled forward, exactly as it is for a weekend day.
410	     */
411	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
412	        LocalDate.parse("2026-01-01"),
413	        LocalDate.parse("2026-01-26"),
414	        LocalDate.parse("2026-04-25"),
415	        LocalDate.parse("2026-12-25"),
416	        LocalDate.parse("2026-12-28"));
417	
418	    /**
419	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
420	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
421	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
422	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
423	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
424	     * falls on a business day.
425	     *
426	     * @param date the effective registration date
427	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
428	     */
429	    private static LocalDate rollToBusinessDay(LocalDate date) {
430	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
431	            date = date.plusDays(1);
432	        }
433	        return date;
434	    }
435	
436	    private static boolean isWeekend(LocalDate date) {
437	        return switch (date.getDayOfWeek()) {
438	            case SATURDAY, SUNDAY -> true;
439	            default -> false;
440	        };
441	    }
