443	    /**
444	     * Counts the existing owners whose {@code registrationDate} equals the given (already
445	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
446	     * business day. Called before a new owner is saved, so the returned value reflects the number of
447	     * owners created for that day prior to this create.
448	     *
449	     * @param date the adjusted business-day registration date to count against
450	     * @return the number of existing owners registered on that date
451	     */
452	    private int countOwnersRegisteredOn(LocalDate date) {
453	        return (int) this.clinicService.findAllOwners().stream()
454	            .filter(existing -> date.equals(existing.getRegistrationDate()))
455	            .count();
456	    }
