458	    /**
459	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
460	     *
461	     * @param city the city to count owners for
462	     * @return the number of existing owners in that city
463	     */
464	    private int countOwnersInCity(String city) {
465	        return (int) this.clinicService.findAllOwners().stream()
