491	     * Counts the existing owners that already belong to the given household (i.e. that share the
492	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
493	     * being created yields the household's total size at the moment of creation. Owners without a
494	     * household id are ignored.
495	     *
496	     * @param householdId the new owner's assigned household id
497	     * @return the number of existing owners already in that household
498	     */
499	    private int countHouseholdMembers(String householdId) {
500	        if (householdId == null) {
501	            return 0;
502	        }
503	        int count = 0;
504	        for (Owner existing : this.clinicService.findAllOwners()) {
505	            if (householdId.equals(existing.getHouseholdId())) {
506	                count++;
507	            }
508	        }
509	        return count;
