512	    /**
513	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
514	     * current maximum effective membership level among the existing owners in that household. The
515	     * ceiling is frozen on the owner at creation and later applied by
516	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
517	     * existing member (or the owner has no household id), meaning no cap applies.
518	     *
519	     * @param householdId the new owner's assigned household id
520	     * @return one above the household's current maximum membership level, or {@code null} when the
521	     *         household has no existing member
522	     */
523	    private Integer householdMembershipLevelCap(String householdId) {
524	        if (householdId == null) {
525	            return null;
526	        }
527	        Integer maxLevel = null;
528	        for (Owner existing : this.clinicService.findAllOwners()) {
529	            if (householdId.equals(existing.getHouseholdId())) {
530	                int level = ownerMapper.toMembershipLevel(existing);
531	                if (maxLevel == null || level > maxLevel) {
532	                    maxLevel = level;
533	                }
534	            }
535	        }
536	        return maxLevel == null ? null : maxLevel + 1;
537	    }
