539	    /**
540	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
541	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
542	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
543	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
544	     * string is what gets stored and returned.
545	     *
546	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
547	     *
548	     * <p>Once in E.164 form the national-number length is validated against the country code: a
549	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
550	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
551	     * rule are accepted on the general 8-to-15 digit length alone.
552	     *
553	     * @param telephone the raw telephone value supplied by the client
554	     * @return the normalized E.164 telephone number
555	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
556	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
557	     *                                 after the {@code '+'}, or the wrong national-number length for
558	     *                                 its country code)
559	     */
560	    private static String normalizeTelephone(String telephone) {
561	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
562	        String digits;
563	        if (cleaned.startsWith("+")) {
564	            digits = cleaned.substring(1);
565	        } else {
566	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
567	            digits = "61" + national;
568	        }
569	        if (!digits.matches("[0-9]{8,15}")) {
570	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
571	                "telephone could not be normalized to a valid E.164 number");
572	        }
573	        validateNationalNumberLength(digits);
574	        return "+" + digits;
575	    }
576	
577	    /**
578	     * Validates the national-number length of an E.164 number (its digits, without the leading
579	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
580	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
581	     * (only the general 8-to-15 digit rule applies).
582	     *
583	     * @param digits the E.164 digits without the leading {@code '+'}
584	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
585	     *                                 digits does not match the country code's required length
586	     */
587	    private static void validateNationalNumberLength(String digits) {
588	        E164PhoneNumbers.countryCode(digits)
589	            .ifPresent(code -> {
590	                int nationalLength = digits.length() - code.length();
591	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
592	                if (nationalLength != required) {
593	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
594	                        "telephone must have " + required
595	                            + " national digits for country code +" + code);
596	                }
597	            });
598	    }
