600	    /**
601	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
602	     * containing at least one dot, none of the three sections containing whitespace or an
603	     * additional {@code @}.
604	     */
605	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
606	
607	    /**
608	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
609	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
610	     * case-insensitively against the domain (the part after the {@code @}).
611	     */
612	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
613	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
614	
615	    /**
616	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
617	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
618	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
619	     * lower-cased.
620	     *
621	     * @param email the raw email value supplied by the client, possibly {@code null}
622	     * @return the lower-cased email, or {@code null} when none was supplied
623	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
624	     *                                 is not a syntactically valid address, or its domain is on the
625	     *                                 disposable-domain blocklist
626	     */
627	    private static String normalizeEmail(String email) {
628	        if (email == null) {
629	            return null;
630	        }
631	        if (!EMAIL_PATTERN.matcher(email).matches()) {
632	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
633	                "email must be a syntactically valid address");
634	        }
635	        String normalized = email.toLowerCase(Locale.ROOT);
636	        String domain = normalized.substring(normalized.indexOf('@') + 1);
637	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
638	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
639	                "email domain " + domain + " is not allowed");
640	        }
641	        return normalized;
642	    }
643	
644	    /**
645	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
646	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
647	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
648	     */
649	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
650	        "NSW", new int[] {2000, 2099},
651	        "VIC", new int[] {3000, 3099},
652	        "QLD", new int[] {4000, 4099});
653	
654	    /**
655	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
656	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
657	     * four-digit format is enforced by request validation; here the value is range-checked: when the
658	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
659	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
660	     * accepts any four-digit postcode.
661	     *
662	     * @param city     the owner's city
663	     * @param postcode the owner's postcode, possibly {@code null}
664	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
665	     *                                 out of range for the city's region
666	     */
667	    private static void validatePostcode(String city, String postcode) {
668	        if (postcode == null) {
669	            return;
670	        }
671	        String region = OwnerMapper.CITY_REGION.get(city);
672	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
673	        if (range == null) {
674	            return;
675	        }
676	        int value = Integer.parseInt(postcode);
677	        if (value < range[0] || value > range[1]) {
678	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
679	                "postcode " + postcode + " is not valid for region " + region);
680	        }
681	    }
682	
683	    /**
684	     * Common street-type abbreviations expanded to their full word during address normalization.
685	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
686	     */
687	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
688	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
689	
690	    /**
691	     * Applies an owner's address, accepting either the structured form (a non-blank
692	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
693	     * preferring the structured fields when present. Whichever fields are supplied are normalized
694	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
695	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
696	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
697	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
698	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
699	     * {@code address} (plus city) is still accepted.
700	     *
701	     * @param owner the owner being created or updated, carrying the raw address fields
702	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
703	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
704	     *                                 supplied
705	     */
706	    private static void applyAddress(Owner owner) {
707	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
708	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
709	        if (!hasStructured && !hasFlat) {
710	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
711	                "an address must be supplied, either 'addressLine1' or 'address'");
712	        }
713	        if (hasStructured) {
714	            String line1 = normalizeAddress(owner.getAddressLine1());
715	            owner.setAddressLine1(line1);
716	            String composed = line1;
717	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
718	                String line2 = normalizeAddress(owner.getAddressLine2());
719	                owner.setAddressLine2(line2);
720	                composed = line1 + " " + line2;
721	            } else {
722	                owner.setAddressLine2(null);
723	            }
724	            owner.setAddress(composed);
725	        } else {
726	            owner.setAddressLine1(null);
727	            owner.setAddressLine2(null);
728	            owner.setAddress(normalizeAddress(owner.getAddress()));
729	        }
730	    }
731	
732	    /**
733	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
734	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
735	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
736	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
737	     *
738	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
739	     *
740	     * @param address the raw address supplied by the client, possibly {@code null}
741	     * @return the normalized address
742	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
743	     *                                 after normalization (required field)
744	     */
745	    private static String normalizeAddress(String address) {
746	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
747	        if (collapsed.isEmpty()) {
748	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
749	                "address must not be blank");
750	        }
751	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
752	        StringBuilder normalized = new StringBuilder();
753	        for (int i = 0; i < tokens.length; i++) {
754	            if (i > 0) {
755	                normalized.append(' ');
756	            }
757	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
758	        }
759	        return normalized.toString();
760	    }
761	
762	    /**
763	     * Determines whether the given whole identity key already belongs to any owner other than the
764	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
765	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
766	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
767	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
768	     *
769	     * @param identityKey the identity key to look for
770	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
771	     * @return {@code true} if another owner already has the same identity key
772	     */
773	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
774	        for (Owner existing : this.clinicService.findAllOwners()) {
775	            if (existing.isDeleted()) {
776	                continue;
777	            }
778	            if (excludeId != null && excludeId.equals(existing.getId())) {
779	                continue;
780	            }
781	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
782	                return true;
783	            }
784	        }
785	        return false;
786	    }
787	
788	    /**
789	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
790	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
791	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
792	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
793	     * this flags only the softer same-household-name overlap — in particular two owners with the same
794	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
795	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
796	     * deterministic when several owners qualify.
797	     *
798	     * @param owner the new owner being created, with its telephone already normalized
799	     * @return the matching existing owner, or {@code null} when none qualifies
800	     */
801	    private Owner findPossibleDuplicate(Owner owner) {
802	        if (owner.getLastName() == null || owner.getPostcode() == null) {
803	            return null;
804	        }
805	        String identityKey = ownerMapper.toIdentityKey(owner);
806	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
807	        return this.clinicService.findAllOwners().stream()
808	            .filter(existing -> !existing.isDeleted())
809	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
810	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
811	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
812	            .min(Comparator.comparingInt(Owner::getId))
813	            .orElse(null);
814	    }
815	
816	}
