47	        expression = "java(toAgeBand(owner))")
48	    @Mapping(target = "telephoneDisplay",
49	        expression = "java(toTelephoneDisplay(owner))")
50	    @Mapping(target = "salutation",
51	        expression = "java(toSalutation(owner))")
52	    @Mapping(target = "fiscalYear",
53	        expression = "java(toFiscalYear(owner))")
54	    @Mapping(target = "selfLink",
55	        expression = "java(toSelfLink(owner))")
56	    OwnerDto toOwnerDto(Owner owner);
57	
58	    /**
59	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
60	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
61	     * then absent from the DTO).
62	     */
63	    default String toSelfLink(Owner owner) {
64	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
65	    }
66	
67	    /**
68	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
69	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
70	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
71	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
72	     * 2026). This is the single source of truth for the fiscal year used both when the create endpoint
73	     * bakes the FY segment into the member id (see {@code OwnerRestControllerV1.memberIdFor}) and when
74	     * the DTO's {@code fiscalYear} falls back to the registration date for a legacy record.
75	     *
76	     * @param date the date to resolve, on a business day
77	     * @return the calendar year in which that date's fiscal year ends
78	     */
79	    static int fiscalYear(LocalDate date) {
80	        int year = date.getYear();
81	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
82	    }
83	
84	    /**
85	     * Derive an owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the two-digit fiscal-year
86	     * segment carried by the {@code memberId} (see {@link #memberIdBase(String)}), e.g. {@code 'FY27'}.
87	     * The fiscal year therefore moves with the owner's member id. When an owner has no (well-formed)
88	     * member id yet (e.g. legacy records) it falls back to deriving the fiscal year directly from the
89	     * business-day-adjusted {@code registrationDate} (see {@link #fiscalYear(LocalDate)}), and returns
90	     * {@code null} when neither is present (the field is then absent from the DTO).
91	     */
92	    default String toFiscalYear(Owner owner) {
93	        String base = memberIdBase(owner.getMemberId());
94	        if (base != null) {
95	            return "FY" + memberIdFyDigits(base);
96	        }
97	        LocalDate registrationDate = owner.getRegistrationDate();
98	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
99	    }
100	
101	    /**
102	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
103	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
104	     * just the last name.
105	     */
106	    default String toSalutation(Owner owner) {
107	        String lastName = owner.getLastName();
108	        String title = owner.getTitle();
109	        if (title == null || title.isBlank()) {
110	            return lastName;
111	        }
112	        return title + " " + lastName;
113	    }
114	
115	    /**
116	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
117	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
118	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
119	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
120	     */
121	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
122	        LocalDate birthDate = owner.getBirthDate();
123	        if (birthDate == null) {
124	            return null;
125	        }
126	        LocalDate reference = owner.getRegistrationDate() != null
127	            ? owner.getRegistrationDate() : LocalDate.now();
128	        int age = Period.between(birthDate, reference).getYears();
129	        if (age < 18) {
130	            return OwnerDto.AgeBandEnum.MINOR;
131	        }
132	        if (age < 65) {
133	            return OwnerDto.AgeBandEnum.ADULT;
134	        }
135	        return OwnerDto.AgeBandEnum.SENIOR;
136	    }
137	
138	    /**
139	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
140	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
141	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
142	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
143	     *
144	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
145	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
146	     * code, a two-digit country code is assumed (the most common length).
147	     */
148	    default String toTelephoneDisplay(Owner owner) {
149	        String telephone = owner.getTelephone();
150	        if (telephone == null || !telephone.startsWith("+")) {
151	            return telephone;
152	        }
153	        String digits = telephone.substring(1);
154	        String code = E164PhoneNumbers.countryCode(digits)
155	            .filter(c -> digits.length() > c.length())
156	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
157	        String national = digits.substring(code.length());
158	        StringBuilder sb = new StringBuilder("+").append(code);
159	        for (int i = 0; i < national.length(); i += 3) {
160	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
161	        }
162	        return sb.toString();
163	    }
164	
165	    /**
166	     * The fixed trailing-segment widths of a member id base {@code '<REGION><FY><HASH8><CHK>'}: FY is 2
167	     * digits, HASH8 is 8 hex characters and CHK is 1 digit, so the last {@link #MEMBER_ID_SUFFIX_WIDTH}
168	     * characters are the {@code <FY><HASH8><CHK>} suffix and REGION is the variable-width remainder in
169	     * front of it. This is the single place the layout is encoded; the position arithmetic in
170	     * {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} derives from these, and it
171	     * must stay in step with how {@code OwnerRestControllerV1.memberIdFor} assembles the id.
172	     */
173	    int FY_WIDTH = 2;
174	    int HASH8_WIDTH = 8;
175	    int CHK_WIDTH = 1;
176	    int MEMBER_ID_SUFFIX_WIDTH = FY_WIDTH + HASH8_WIDTH + CHK_WIDTH;
177	
178	    /**
179	     * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
180	     * suffix, or {@code null} when the owner has no (well-formed) member id yet — i.e. one long enough to
181	     * carry a non-empty REGION in front of the fixed {@link #MEMBER_ID_SUFFIX_WIDTH}-character suffix.
182	     * Use {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} to decode its segments.
183	     */
184	    private static String memberIdBase(String memberId) {
185	        if (memberId == null) {
186	            return null;
187	        }
188	        int dash = memberId.indexOf('-');
189	        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
190	        return base.length() > MEMBER_ID_SUFFIX_WIDTH ? base : null;
191	    }
192	
193	    /**
194	     * The leading {@code <REGION>} segment of a (non-null, well-formed) member id base: everything
195	     * before the fixed trailing {@code <FY><HASH8><CHK>} suffix.
196	     */
197	    private static String memberIdRegion(String base) {
198	        return base.substring(0, base.length() - MEMBER_ID_SUFFIX_WIDTH);
199	    }
200	
201	    /**
202	     * The two-digit {@code <FY>} segment of a (non-null, well-formed) member id base: the characters
203	     * immediately preceding the trailing HASH8 and CHK segments.
204	     */
205	    private static String memberIdFyDigits(String base) {
206	        int fyEnd = base.length() - HASH8_WIDTH - CHK_WIDTH;
207	        return base.substring(fyEnd - FY_WIDTH, fyEnd);
208	    }
209	
210	    /**
211	     * Derive an owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64
212	     * characters) of the normalized E.164 telephone, the lower-cased email (empty when none) and the
213	     * American Soundex code of the last name, joined with {@code '|'}. Two owners are duplicates only
214	     * when their whole identity keys are equal.
215	     *
216	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
217	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
218	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}, and the Soundex and
219	     * hashing come from {@link IdentityKeyUtils}, the same helpers the soft-match uses.
220	     */
221	    default String toIdentityKey(Owner owner) {
222	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
223	        String email = hasEmail(owner) ? owner.getEmail() : "";
224	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
225	        return IdentityKeyUtils.sha256Hex(telephone + "|" + email + "|" + soundex);
226	    }
227	
228	    /**
229	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
230	     * for the "is an email present" rule shared by the derived fields below.
231	     */
232	    default boolean hasEmail(Owner owner) {
233	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
234	    }
235	
236	    /**
237	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
238	     * otherwise 'PHONE'.
239	     */
240	    default String toContactPreference(Owner owner) {
241	        return hasEmail(owner) ? "EMAIL" : "PHONE";
242	    }
243	
244	    /**
245	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
246	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
247	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
248	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
249	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
250	     * and no namesakes in a single-member household scores 3 points.
251	     */
252	    default Integer toMembershipPoints(Owner owner) {
253	        int points = 0;
254	        if (hasEmail(owner)) {
255	            points += 2;
256	        }
257	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
258	        if (noNamesakes) {
259	            points += 1;
260	        }
261	        if (hasHouseholdBonus(owner)) {
262	            points += 2;
263	        }
264	        if (hasTenureBonus(owner)) {
265	            points += 3;
266	        }
267	        return points;
268	    }
269	
270	    /**
271	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
272	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
273	     * Returns {@code false} when no household size is present (e.g. legacy records).
274	     */
275	    default boolean hasHouseholdBonus(Owner owner) {
276	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
277	    }
278	
279	    /**
280	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
281	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
282	     * or more.
283	     *
284	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
285	     * owner's membership level cannot exceed one above the current maximum membership level among their
286	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
287	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
288	     * member, or a legacy record) the uncapped level stands.
289	     */
290	    default Integer toMembershipLevel(Owner owner) {
291	        int level = uncappedMembershipLevel(owner);
292	        Integer cap = owner.getMembershipLevelCap();
293	        if (cap != null && level > cap) {
294	            return cap;
295	        }
296	        return level;
297	    }
298	
299	    /**
300	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
301	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
302	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
303	     */
304	    default Integer uncappedMembershipLevel(Owner owner) {
305	        int points = toMembershipPoints(owner);
306	        if (points <= 1) {
307	            return 1;
308	        }
309	        if (points <= 3) {
310	            return 2;
311	        }
312	        if (points <= 5) {
313	            return 3;
314	        }
315	        return 4;
316	    }
317	
318	    /**
319	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
320	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
321	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
322	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
323	     * no registration date is present.
324	     */
325	    default boolean hasTenureBonus(Owner owner) {
326	        LocalDate registrationDate = owner.getRegistrationDate();
327	        if (registrationDate == null) {
328	            return false;
329	        }
330	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
331	    }
332	
333	    /**
334	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
335	     */
336	    Map<String, String> CITY_REGION = Map.of(
337	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
338	
339	    /**
340	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
341	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
342	     * inclusive.
343	     */
344	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
345	        "NSW", new int[] {2000, 2099},
346	        "VIC", new int[] {3000, 3099},
347	        "QLD", new int[] {4000, 4099});
348	
349	    /**
350	     * Derive an owner's locality (region) from the region-and-hash member id: the leading
351	     * {@code <REGION>} segment of the {@code memberId}, i.e. everything before its trailing FY, HASH8
352	     * and CHK segments (see {@link #memberIdBase(String)}). Since the region is baked into the member id
353	     * at creation (see the create endpoint), the locality now moves with that identity rather than being
354	     * recomputed from the postcode and city. When an owner has no (well-formed) member id yet (e.g.
355	     * legacy records), fall back to deriving the region directly via {@link #regionOf(Owner)}.
356	     */
357	    default String toLocality(Owner owner) {
358	        String base = memberIdBase(owner.getMemberId());
359	        if (base != null) {
360	            return memberIdRegion(base);
361	        }
362	        return regionOf(owner);
363	    }
364	
365	    /**
366	     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
367	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
368	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
369	     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
370	     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
371	     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
372	     * {@code 'REGIONAL'}.
373	     */
374	    default String toOwnerSegment(Owner owner) {
375	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
376	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
377	        return tier + "_" + area;
378	    }
379	
380	    /**
381	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
382	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
383	     */
384	    Map<String, String> REGION_TIMEZONE = Map.of(
385	        "NSW", "Australia/Sydney",
386	        "VIC", "Australia/Melbourne",
387	        "QLD", "Australia/Brisbane");
388	
389	    /**
390	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
391	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
392	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
393	     */
394	    default String toTimezone(Owner owner) {
395	        return REGION_TIMEZONE.get(toLocality(owner));
396	    }
397	
398	    /**
399	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
400	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
401	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
402	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
403	     * the leading {@code <REGION>} segment of a new owner's member id and, through it, the owner's
404	     * locality.
405	     */
406	    default String regionOf(Owner owner) {
407	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
408	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
409	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
410	        String postcode = owner.getPostcode();
411	        if (postcode != null) {
412	            try {
413	                int value = Integer.parseInt(postcode.trim());
414	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
415	                    int[] range = entry.getValue();
416	                    if (value >= range[0] && value <= range[1]) {
417	                        return entry.getKey();
418	                    }
419	                }
420	            }
421	            catch (NumberFormatException ignored) {
422	                // Non-numeric postcode: fall back to the city table below.
423	            }
424	        }
425	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
426	    }
427	
428	    Owner toOwner(OwnerDto ownerDto);
429	
430	    @Mapping(target = "id", ignore = true)
431	    @Mapping(target = "pets", ignore = true)
432	    Owner toOwner(OwnerFieldsDto ownerDto);
433	
434	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
435	
436	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
437	
438	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
439	        OwnerPageDto ownerPageDto = new OwnerPageDto();
440	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
441	        ownerPageDto.setPage(ownerPage.getNumber());
442	        ownerPageDto.setSize(ownerPage.getSize());
443	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
444	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
445	        return ownerPageDto;
446	    }
447	}
